{
  "name": "HDF5数据浏览器",
  "name_en": "HDF5 Data Browser",
  "manufacturer": "",
  "description": "用于实验室数据管理与查看的软件工具，可打开和浏览HDF5（.h5）文件，查看树状数据节点、属性、图像和曲线，并导出选定子数据。",
  "description_en": "A software tool for laboratory data inspection and management that opens and browses HDF5 (.h5) files, displays hierarchical data nodes, attributes, images, and plotted data, and exports selected subdatasets.",
  "tag_hints": [
    "HDF5 data browsing",
    "experimental data visualization",
    "dataset export",
    "metadata inspection",
    "image display",
    "lab data management"
  ],
  "actions": [
    {
      "action_name": "auto-connect_things",
      "description": "连接界面信号与功能。",
      "description_en": "Connect UI signals and functions."
    },
    {
      "action_name": "auto-get_node_and_plot",
      "description": "获取所选节点并绘制其数据。",
      "description_en": "Get the selected node and plot its data."
    },
    {
      "action_name": "auto-load_file",
      "description": "加载HDF5文件。",
      "description_en": "Load an HDF5 file."
    },
    {
      "action_name": "auto-setup_menu",
      "description": "设置浏览器菜单。",
      "description_en": "Set up the browser menu."
    },
    {
      "action_name": "auto-setup_actions",
      "description": "设置可用操作项。",
      "description_en": "Set up available actions."
    },
    {
      "action_name": "auto-check_version",
      "description": "检查文件与浏览器的版本兼容性。",
      "description_en": "Check version compatibility between the file and the browser."
    },
    {
      "action_name": "auto-add_comments",
      "description": "向当前节点添加注释。",
      "description_en": "Add a comment to the current node."
    },
    {
      "action_name": "auto-get_tree_node_path",
      "description": "获取当前选中树节点的路径。",
      "description_en": "Get the path of the currently selected tree node."
    },
    {
      "action_name": "auto-export_data",
      "description": "导出所选数据。",
      "description_en": "Export selected data."
    },
    {
      "action_name": "auto-save_file",
      "description": "保存当前HDF5文件。",
      "description_en": "Save the current HDF5 file."
    },
    {
      "action_name": "auto-quit_fun",
      "description": "退出浏览器。",
      "description_en": "Quit the browser."
    },
    {
      "action_name": "auto-show_about",
      "description": "显示关于信息。",
      "description_en": "Show the about information."
    },
    {
      "action_name": "auto-show_log",
      "description": "显示日志信息。",
      "description_en": "Show log information."
    },
    {
      "action_name": "auto-show_help",
      "description": "显示帮助信息。",
      "description_en": "Show help information."
    },
    {
      "action_name": "auto-add_log",
      "description": "添加日志文本。",
      "description_en": "Add log text."
    },
    {
      "action_name": "auto-show_h5_attributes",
      "description": "显示HDF5属性。",
      "description_en": "Show HDF5 attributes."
    },
    {
      "action_name": "auto-show_pixmaps",
      "description": "显示图像数据。",
      "description_en": "Show image data."
    },
    {
      "action_name": "auto-show_h5_data",
      "description": "显示所选HDF5数据并可绘图。",
      "description_en": "Display selected HDF5 data and plot it."
    },
    {
      "action_name": "auto-populate_tree",
      "description": "填充并显示数据树。",
      "description_en": "Populate and display the data tree."
    }
  ]
}

